mapper.select:
SELECT history.*
FROM wf_deploy_rollback_history history
JOIN wf_deploy_record deployment ON deployment.id = history.original_deploy_id
    AND deployment.tenant_id = history.tenant_id
WHERE deployment.process_def_id = #{definitionId}
  AND deployment.tenant_id = #{tenantId}
  AND history.tenant_id = #{tenantId}
ORDER BY history.rollback_time DESC, history.id DESC
